public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0) throw new IllegalArgumentException("n must be positive");
    if (start == null || end == null) throw new IllegalArgumentException("start or end cannot be null");
    if (start.length != 2 || end.length != 2) throw new IllegalArgumentException("start and end must have exactly two coordinates");
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n)
        throw new IllegalArgumentException("start coordinates out of bounds");
    if (end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n)
        throw new IllegalArgumentException("end coordinates out of bounds");
    if (paths == null) throw new IllegalArgumentException("paths cannot be null");

    // If start equals end, travel is trivially possible
    if (start[0] == end[0] && start[1] == end[1]) return "can be travelled";

    // Build adjacency list
    Map<String, List<String>> adjacency = new HashMap<>();
    String startKey = start[0] + "," + start[1];
    String endKey = end[0] + "," + end[1];
    adjacency.putIfAbsent(startKey, new ArrayList<>());
    adjacency.putIfAbsent(endKey, new ArrayList<>());

    for (int[] p : paths) {
        if (p == null || p.length != 4) continue; // skip malformed entries
        int r1 = p[0], c1 = p[1], r2 = p[2], c2 = p[3];
        if (r1 < 0 || r1 >= n || c1 < 0 || c1 >= n ||
            r2 < 0 || r2 >= n || c2 < 0 || c2 >= n) continue; // ignore out‑of‑bounds edges
        String a = r1 + "," + c1;
        String b = r2 + "," + c2;
        adjacency.computeIfAbsent(a, k -> new ArrayList<>()).add(b);
        adjacency.computeIfAbsent(b, k -> new ArrayList<>()).add(a);
    }

    // Breadth‑first search from start to end
    Set<String> visited = new HashSet<>();
    Queue<String> queue = new LinkedList<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        if (current.equals(endKey)) return "can be travelled";
        for (String neighbor : adjacency.getOrDefault(current, Collections.emptyList())) {
            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

