public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int i = 0;
    int n = s.length();
    while (i < n) {
        if (s.charAt(i) == ' ') {
            result.append(' ');
            i++;
        } else {
            int start = i;
            while (i < n && s.charAt(i) != ' ') {
                i++;
            }
            for (int j = i - 1; j >= start; j--) {
                result.append(s.charAt(j));
            }
        }
    }
    return result.toString();
}
